{
  "items": [
    {
      "path": "tools.hypernexus.add_memory",
      "description": "Store a structured memory in the L2 vector vault",
      "signature": "tools.hypernexus.add_memory({\n  /** Category (default general) */\n  category?: string,\n  /** Memory content (required) */\n  content: string,\n  /** Importance 0-1 (default 0.5) */\n  importance?: number,\n  /** Session identifier */\n  session_id?: string,\n  /** Comma-separated tags */\n  tags?: string,\n}): Promise<unknown>"
    },
    {
      "path": "tools.hypernexus.delete_memory",
      "description": "Delete an L2 vault memory by ID",
      "signature": "tools.hypernexus.delete_memory({\n  /** Memory ID to delete */\n  id: string,\n}): Promise<unknown>"
    },
    {
      "path": "tools.hypernexus.memory_delete",
      "description": "Delete an L2 memory by id, or every memory carrying a tag (capped fan-out). Use for cleanup of stale or wrong facts.",
      "signature": "tools.hypernexus.memory_delete({\n  /** Memory id to delete (from search/list results). */\n  id?: string,\n  /** Alternative: delete all memories carrying this tag (max 20). */\n  tag?: string,\n}): Promise<string | null>"
    },
    {
      "path": "tools.hypernexus.memory_fts_search",
      "description": "FAST keyword search across L2 memory (FTS). Prefer this in latency-sensitive loops.",
      "signature": "tools.hypernexus.memory_fts_search({\n  /** Search query. */\n  query: string,\n  /** Max results (default 8) */\n  limit?: number,\n}): Promise<string | null>"
    },
    {
      "path": "tools.hypernexus.memory_scratchpad_append",
      "description": "Append text to an existing core memory scratchpad value",
      "signature": "tools.hypernexus.memory_scratchpad_append({\n  /** Key to append to */\n  key: string,\n  /** Content/text to append */\n  value: string,\n}): Promise<unknown>"
    },
    {
      "path": "tools.hypernexus.memory_scratchpad_get",
      "description": "Retrieve a value from the core memory scratchpad (e.g. 'persona' or 'human')",
      "signature": "tools.hypernexus.memory_scratchpad_get({\n  /** Key to retrieve */\n  key: string,\n}): Promise<unknown>"
    },
    {
      "path": "tools.hypernexus.memory_scratchpad_set",
      "description": "Write/overwrite a value in the core memory scratchpad",
      "signature": "tools.hypernexus.memory_scratchpad_set({\n  /** Key to set */\n  key: string,\n  /** Content/value to write */\n  value: string,\n}): Promise<unknown>"
    },
    {
      "path": "tools.hypernexus.memory_search",
      "description": "Keyword + semantic search across L2 memory (slower, best relevance). Use for explicit lookups before re-deriving known answers; for hot loops use memory_fts_search instead.",
      "signature": "tools.hypernexus.memory_search({\n  /** Search query. */\n  query: string,\n  /** Max results (default 8) */\n  limit?: number,\n}): Promise<string | null>"
    },
    {
      "path": "tools.hypernexus.memory_stats",
      "description": "Memory tier statistics: counts across L2 vault, scratchpad, and relation tiers.",
      "signature": "tools.hypernexus.memory_stats(): Promise<string | null>"
    },
    {
      "path": "tools.hypernexus.memory_store",
      "description": "Persist a fact, decision, or gotcha to HyperNexus L2 memory with tags (survives across sessions/tools).",
      "signature": "tools.hypernexus.memory_store({\n  /** The memory content (markdown/plain text). */\n  content: string,\n  /** Optional short title. */\n  title?: string,\n  /**\n   * Tags, e.g. ['deployment','bug-fix'].\n   * Each item: tag\n   */\n  tags?: Array<string>,\n  /** Namespace: project | global | user (default project). */\n  namespace?: string,\n}): Promise<string | null>"
    }
  ],
  "remaining": 80,
